 if(isset($_GET['admin'])){requireStaff($pdo,$config);$page=max((int)($_GET['page']??1),1);$limit=min(max((int)($_GET['limit']??20),5),100);$offset=($page-1)*$limit;$search=trim((string)($_GET['q']??''));$where='';$params=[];if($search!==''){$where='WHERE p.title LIKE ? OR p.author LIKE ? OR c.name LIKE ? OR p.status LIKE ?';$term='%'.$search.'%';$params=[$term,$term,$term,$term];}$count=$pdo->prepare("SELECT COUNT(*) FROM posts p LEFT JOIN categories c ON c.id=p.category_id $where");$count->execute($params);$total=(int)$count->fetchColumn();$q=$pdo->prepare("SELECT p.id,p.language,p.translation_key,p.updated_at,p.slug,p.title,p.excerpt,p.author,p.status,p.published_at,p.created_at,c.name category_name FROM posts p LEFT JOIN categories c ON c.id=p.category_id $where ORDER BY p.created_at DESC LIMIT $limit OFFSET $offset");$q->execute($params);exit(json_encode(['data'=>$q->fetchAll(),'pagination'=>['page'=>$page,'limit'=>$limit,'total'=>$total,'pages'=>(int)ceil($total/$limit),'has_more'=>$offset+$limit<$total]]));}
 $slug=$_GET['slug']??null;
