 $limit=min(max((int)($_GET['limit']??10),1),25);$page=max((int)($_GET['page']??1),1);$offset=($page-1)*$limit;$category=trim((string)($_GET['category']??''));$where="p.status='published'";$params=[];if(isset($_GET['language'])){$where.=' AND p.language=?';$params[]=postLanguage($_GET['language']);}if($category!==''){$where.=' AND c.name=?';$params[]=$category;}$count=$pdo->prepare("SELECT COUNT(*) FROM posts p LEFT JOIN categories c ON c.id=p.category_id WHERE $where");$count->execute($params);$total=(int)$count->fetchColumn();$q=$pdo->prepare("SELECT p.id,p.language,p.translation_key,p.updated_at,p.slug,p.title,p.excerpt,p.content,p.image_url,p.image_alt,p.author,p.published_at,c.name category_name,(SELECT COUNT(*) FROM post_likes l WHERE l.post_slug=p.slug) like_count,(SELECT COUNT(*) FROM comments m WHERE m.post_slug=p.slug AND m.status='visible') comment_count FROM posts p LEFT JOIN categories c ON c.id=p.category_id WHERE $where ORDER BY p.published_at DESC,p.id DESC LIMIT $limit OFFSET $offset");$q->execute($params);$rows=$q->fetchAll();foreach($rows as &$row)$row['content']=sanitizeRichText((string)$row['content']);unset($row);exit(json_encode(['data'=>$rows,'pagination'=>['page'=>$page,'limit'=>$limit,'total'=>$total,'pages'=>max(1,(int)ceil($total/$limit)),'has_more'=>$offset+count($rows)<$total]]));
}
